package com.example.todo

import android.app.*
import android.os.Bundle
import android.view.*
import android.widget.*
import androidx.fragment.app.Fragment
import java.util.*

class TaskEditorFragment : Fragment() {
    private lateinit var task: Task; private lateinit var title: EditText; private lateinit var description: EditText; private var due: Long? = null; private var selectedCategory: Long? = null
    companion object { fun newInstance(task: Task?) = TaskEditorFragment().apply { arguments = Bundle().apply { putLong("id", task?.id ?: 0); putString("title", task?.title ?: ""); putString("description", task?.description ?: ""); putBoolean("completed", task?.completed ?: false); putLong("due", task?.dueDateTime ?: 0); putLong("category", task?.categoryId ?: 0) } } }
    override fun onCreate(b: Bundle?) { super.onCreate(b); val a = requireArguments(); task = Task(a.getLong("id"), a.getString("title").orEmpty(), a.getString("description").orEmpty(), a.getBoolean("completed"), a.getLong("due").takeIf { it != 0L }, System.currentTimeMillis(), a.getLong("category").takeIf { it != 0L }); due = task.dueDateTime; selectedCategory = task.categoryId }
    override fun onCreateView(i: LayoutInflater, c: ViewGroup?, b: Bundle?): View { val ctx = requireContext(); val box = root(ctx); box.addView(text(ctx, if (task.id == 0L) "Nova tarefa" else "Editar tarefa", 26f)); title = EditText(ctx); title.hint = "Título (obrigatório)"; title.setText(task.title); box.addView(title); description = EditText(ctx); description.hint = "Descrição"; description.setText(task.description); box.addView(description); val category = Spinner(ctx); box.addView(category); (activity as MainActivity).viewModel().categories.observe(viewLifecycleOwner) { cats -> category.adapter = ArrayAdapter(ctx, android.R.layout.simple_spinner_dropdown_item, listOf("Sem categoria") + cats.map { it.name }); val index = cats.indexOfFirst { it.id == selectedCategory }; category.setSelection(index + 1); category.onItemSelectedListener = object : AdapterView.OnItemSelectedListener { override fun onNothingSelected(p: AdapterView<*>?) {}; override fun onItemSelected(p: AdapterView<*>?, v: View?, pos: Int, id: Long) { selectedCategory = cats.getOrNull(pos - 1)?.id } } }; val date = Button(ctx).apply { text = due?.let { "Vencimento: ${Date(it)}" } ?: "Adicionar vencimento"; setOnClickListener { chooseDate(this) } }; box.addView(date); if (due != null) box.addView(Button(ctx).apply { text = "Remover vencimento"; setOnClickListener { due = null; date.text = "Adicionar vencimento"; visibility = View.GONE } }); val done = CheckBox(ctx).apply { text = "Concluída"; isChecked = task.completed }; box.addView(done); val actions = LinearLayout(ctx); actions.addView(Button(ctx).apply { text = "Cancelar"; setOnClickListener { requireActivity().onBackPressedDispatcher.onBackPressed() } }); actions.addView(Button(ctx).apply { text = "Salvar"; setOnClickListener { val value = title.text.toString().trim(); if (value.isEmpty()) { title.error = "Informe um título"; return@setOnClickListener }; val saved = task.copy(title = value, description = description.text.toString(), completed = done.isChecked, dueDateTime = due, categoryId = selectedCategory); (activity as MainActivity).viewModel().saveTask(saved) { ReminderScheduler.schedule(requireContext(), saved); requireActivity().runOnUiThread { requireActivity().onBackPressedDispatcher.onBackPressed() } } } }); if (task.id != 0L) actions.addView(Button(ctx).apply { text = "Excluir"; setOnClickListener { (activity as MainActivity).viewModel().deleteTask(task) { ReminderScheduler.cancel(requireContext(), task.id); requireActivity().runOnUiThread { requireActivity().onBackPressedDispatcher.onBackPressed() } } } }); box.addView(actions); return ScrollView(ctx).apply { addView(box) } }
    private fun chooseDate(button: Button) { val now = Calendar.getInstance(); DatePickerDialog(requireContext(), { _, y, m, d -> TimePickerDialog(requireContext(), { _, h, min -> due = Calendar.getInstance().apply { set(y, m, d, h, min, 0) }.timeInMillis; button.text = "Vencimento: ${Date(due!!)}" }, now.get(Calendar.HOUR_OF_DAY), now.get(Calendar.MINUTE), true).show() }, now.get(Calendar.YEAR), now.get(Calendar.MONTH), now.get(Calendar.DAY_OF_MONTH)).show() }
}

class CategoryFragment : Fragment() {
    override fun onCreateView(i: LayoutInflater, c: ViewGroup?, b: Bundle?): View { val ctx = requireContext(); val box = root(ctx); box.addView(text(ctx, "Categorias", 26f)); val input = EditText(ctx); input.hint = "Nome da categoria"; box.addView(input); box.addView(Button(ctx).apply { text = "Adicionar"; setOnClickListener { val name = input.text.toString().trim(); if (name.isNotEmpty()) { model().saveCategory(Category(name = name)); input.text.clear() } } }); val list = LinearLayout(ctx).apply { orientation = LinearLayout.VERTICAL }; box.addView(list); model().categories.observe(viewLifecycleOwner) { cats -> list.removeAllViews(); cats.forEach { category -> val row = LinearLayout(ctx); row.addView(text(ctx, category.name), LinearLayout.LayoutParams(0, -2, 1f)); row.addView(Button(ctx).apply { text = "Renomear"; setOnClickListener { val edit = EditText(ctx); edit.setText(category.name); AlertDialog.Builder(ctx).setTitle("Renomear categoria").setView(edit).setNegativeButton("Cancelar", null).setPositiveButton("Salvar") { _, _ -> val name = edit.text.toString().trim(); if (name.isNotEmpty()) model().saveCategory(category.copy(name = name)) }.show() } }); row.addView(Button(ctx).apply { text = "Excluir"; setOnClickListener { model().deleteCategory(category) } }); list.addView(row) } }; return ScrollView(ctx).apply { addView(box) } }
    private fun model(): TodoViewModel = (activity as MainActivity).viewModel()
}
